  2	import { STORE_NAMES } from "../db/schema";
  3	import { assertAbsoluteIsoTimestamp } from "../db/timestamps";
  4	import type { StoredFile } from "../db/types";
  5	
  6	export type StoredFileInput = Omit<StoredFile, "id" | "createdAt" | "updatedAt">;
  7	
  8	export interface BlobStoreDependencies {
  9	  now?: () => string;
 10	  createId?: () => string;
 11	}
 12	
 13	const MAX_FILE_SIZE = 25 * 1024 * 1024;
 14	
 15	function validateInput(input: StoredFileInput): void {
 16	  if (input.fileType !== "pdf" && input.fileType !== "docx") {
 17	    throw new Error("Invalid original file type: only PDF and DOCX are supported");
 18	  }
 19	  if (
 20	    typeof input.blob !== "object" ||
 21	    typeof input.blob.size !== "number" ||
 22	    typeof input.blob.type !== "string" ||
 23	    typeof input.blob.slice !== "function"
 24	  ) {
 25	    throw new Error("Invalid original file Blob");
 26	  }
 27	  if (input.blob.size > MAX_FILE_SIZE) {
 28	    throw new Error("Invalid original file size: maximum is 25 MB");
 29	  }
 30	}
 31	
 32	export class BlobStore {
 33	  readonly #database: IDBDatabase;
 34	  readonly #now: () => string;
 35	  readonly #createId: () => string;
 36	
 37	  constructor(database: IDBDatabase, dependencies: BlobStoreDependencies = {}) {
 38	    this.#database = database;
 39	    this.#now = dependencies.now ?? (() => new Date().toISOString());
 40	    this.#createId = dependencies.createId ?? (() => crypto.randomUUID());
 41	  }
 42	
 43	  async save(input: StoredFileInput): Promise<StoredFile> {
 44	    validateInput(input);
 45	    const timestamp = this.#now();
 46	    assertAbsoluteIsoTimestamp(timestamp, "original file timestamp");
 47	    const record: StoredFile = {
 48	      ...input,
 49	      id: this.#createId(),
 50	      createdAt: timestamp,
 51	      updatedAt: timestamp,
 52	    };
 53	
 54	    await runTransaction(
 55	      this.#database,
 56	      STORE_NAMES.originalFiles,
 57	      "readwrite",
 58	      (transaction) =>
 59	        requestToPromise(
 60	          transaction.objectStore(STORE_NAMES.originalFiles).add(record),
 61	        ),
 62	    );
 63	    return record;
 64	  }
 65	
 66	  get(id: string): Promise<StoredFile | undefined> {
 67	    return runTransaction(
 68	      this.#database,
 69	      STORE_NAMES.originalFiles,
 70	      "readonly",
 71	      (transaction) =>
 72	        requestToPromise<StoredFile | undefined>(
 73	          transaction.objectStore(STORE_NAMES.originalFiles).get(id),
 74	        ),
 75	    );
 76	  }
 77	
 78	  list(): Promise<StoredFile[]> {
 79	    return runTransaction(
 80	      this.#database,
 81	      STORE_NAMES.originalFiles,
 82	      "readonly",
 83	      (transaction) =>
 84	        requestToPromise<StoredFile[]>(
 85	          transaction.objectStore(STORE_NAMES.originalFiles).getAll(),
 86	        ),
 87	    );
 88	  }
 89	
 90	  async delete(id: string): Promise<void> {
 91	    await runTransaction(
 92	      this.#database,
 93	      STORE_NAMES.originalFiles,
 94	      "readwrite",
 95	      (transaction) =>
 96	        requestToPromise(
 97	          transaction.objectStore(STORE_NAMES.originalFiles).delete(id),
 98	        ),
 99	    );
100	  }
101	}

